fbf8b",6],["7a7922a0-95c1-4b53-b324-1829cfc9252b",6],["b06ab06c-7f27-4d11-9b15-c1e6e4a20c1f",8],["c894d1b9-8c80-4f36-9fef-c2f09cc445a7",7],["812856a1-a6a5-46fe-99ca-fd8f13d1dccd",8],["b845cbc8-1b4f-4047-b1f3-989e4f77f3d5",7],["d05b8a64-48f3-435f-9210-01afa8afa9a3",8],["0f0fddc8-42bc-4351-ab51-d065a0185932",7],["5f1eb6f8-48e5-4000-9f8b-9e83c272e1b5",8],["7e3cee15-ae8c-4e6a-aaf4-12d330ef2941",10],["e1081ced-3f74-496f-9c6d-1f4c710f043f",8],["f04940f0-f859-4318-bf19-2b7d083b6040",6],["eaee0ea3-80fd-468b-8e63-1fbfc13f9e28",6],["5d5b93f7-a428-4446-b16c-526c107ac8a6",8],["b99d1441-74bb-4dc9-aaa7-9cd9e6a57476",6],["494759ee-84b0-49a8-9dc0-ad72c9c26de8",10],["8318f2ac-83eb-4e59-8e43-81a43da19aba",7],["35baa72c-705a-4702-b318-fa9667d95c38",8],["94c0b9d8-44d5-4952-a8ae-ebd7c957802e",10],["7fcf758f-52d6-4595-8b9a-ff09ac536b7f",7],["3783e0ae-737d-4166-9d21-f073ccd8fb0c",7],["d643f4d2-cb4a-489f-8085-ba0ab9a128ba",7],["fe39e4bf-0c21-4c69-9818-f9b44152e339",6]]}]'::jsonb;
  v_item jsonb;
  v_nota jsonb;
  v_turma_id uuid;
  v_disc_id uuid;
  v_bim int;
  v_prof_id uuid;
  v_aval_id uuid;
  v_nome_aval text;
  v_pulados int := 0;
  v_grupos int := 0;
  v_notas int := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(v_payload) LOOP
    v_turma_id := (v_item->>'t')::uuid;
    v_disc_id := (v_item->>'d')::uuid;
    v_bim := (v_item->>'b')::int;

    SELECT professor_id INTO v_prof_id FROM public.alocacoes_v2
      WHERE turma_id = v_turma_id AND disciplina_id = v_disc_id LIMIT 1;

    IF v_prof_id IS NULL THEN
      RAISE NOTICE 'sem professor alocado - turma % disciplina % bimestre % (% notas puladas)', v_turma_id, v_disc_id, v_bim, jsonb_array_length(v_item->'n');
      v_pulados := v_pulados + 1;
      CONTINUE;
    END IF;

    v_nome_aval := v_bim || 'o Bimestre (Historico)';

    SELECT id INTO v_aval_id FROM public.avaliacoes
      WHERE turma_id = v_turma_id::text AND disciplina_id = v_disc_id::text AND bimestre_id = v_bim AND nome = v_nome_aval;

    IF v_aval_id IS NULL THEN
      INSERT INTO public.avaliacoes (professor_id, turma_id, disciplina_id, bimestre_id, nome, valor_maximo, data_avaliacao, publicada)
      VALUES (v_prof_id, v_turma_id::text, v_disc_id::text, v_bim, v_nome_aval, 10, NULL, true)
      RETURNING id INTO v_aval_id;
    END IF;

    FOR v_nota IN SELECT * FROM jsonb_array_elements(v_item->'n') LOOP
      INSERT INTO public.notas_avaliacoes (avaliacao_id, aluno_id, nota)
      VALUES (v_aval_id, (v_nota->>0)::uuid, (v_nota->>1)::numeric)
      ON CONFLICT (avaliacao_id, aluno_id) DO UPDATE SET nota = EXCLUDED.nota;
      v_notas := v_notas + 1;
    END LOOP;

    v_grupos := v_grupos + 1;
  END LOOP;

  RAISE NOTICE 'IMPORTACAO CONCLUIDA: % grupos (turma+disciplina+bimestre) importados, % notas gravadas, % grupos pulados por falta de professor alocado', v_grupos, v_notas, v_pulados;
END;
$$;
